v:[['Joshua 11:10-13','Joshua captures Hazor and burns it.'],['Judges 4:2','Jabin, king of Canaan, who reigned in Hazor.'],['1 Kings 9:15','Solomon builds Hazor, Megiddo and Gezer.'],['2 Kings 15:29','Tiglath-Pileser takes Hazor.']],
